-- Carico testi residente nel catalogo (maintenance_templates). Una sola chiamata = una transazione implicita.
-- 1) conserva il testo tecnico attuale
update public.maintenance_templates set technical_notes = description where is_active and description is not null and technical_notes is null;
-- 2) testi approvati, per uuid completo (prefisso -> uuid risolto da id::text like)
update public.maintenance_templates set description=$cz$Le grondaie raccolgono l’acqua che scende dal tetto. Foglie e detriti possono ostruirle.$cz$, why_it_matters=$cz$Una grondaia libera fa defluire la pioggia e limita infiltrazioni e danni alle facciate.$cz$, who_does_it=$cz$Impresa specializzata in coperture. Tu non devi intervenire: se noti perdite o traboccamenti, avvisa l’amministratore.$cz$, what_to_keep=$cz$Rapporto di pulizia delle grondaie, con eventuali fotografie.$cz$, how_to=null where is_active and id::text like 'd9b03bd4%';
update public.maintenance_templates set description=$cz$Il manto di copertura è la parte esterna del tetto che ferma la pioggia. Si cercano tegole o elementi danneggiati e spostati.$cz$, why_it_matters=$cz$Individuare piccoli problemi sul tetto aiuta a prevenire infiltrazioni più costose.$cz$, who_does_it=$cz$Coperturista o impresa edile attrezzata per lavorare in quota. Tu segnala all’amministratore macchie d’umidità e perdite.$cz$, what_to_keep=$cz$Rapporto di ispezione del tetto, con fotografie.$cz$, how_to=null where is_active and id::text like 'f0c52720%';
update public.maintenance_templates set description=$cz$I lucernari sono finestre inserite nel tetto. Si controllano apertura, guarnizioni e tenuta all’acqua.$cz$, why_it_matters=$cz$Un controllo tempestivo può evitare infiltrazioni, spifferi e difficoltà di apertura.$cz$, who_does_it=$cz$Serramentista o tecnico delle coperture. Tu avvisa l’amministratore se noti infiltrazioni o blocchi.$cz$, what_to_keep=$cz$Rapporto di verifica dei lucernari.$cz$, how_to=null where is_active and id::text like 'b95a07e2%';
update public.maintenance_templates set description=$cz$L’antenna o parabola riceve il segnale televisivo. Si controllano fissaggi, collegamenti e ricezione.$cz$, why_it_matters=$cz$Riduce il rischio di distacchi col vento e di interruzioni del segnale.$cz$, who_does_it=$cz$Antennista o impresa abilitata per gli impianti radiotelevisivi. Tu segnala all’amministratore perdite di segnale.$cz$, what_to_keep=$cz$Rapporto di verifica dell’impianto antenna.$cz$, how_to=null where is_active and id::text like '3fb467a8%';
update public.maintenance_templates set description=$cz$La cappa aspira vapori e grassi mentre cucini. Filtri e condotti possono sporcarsi e ridurre l’aspirazione.$cz$, why_it_matters=$cz$Una pulizia corretta migliora il funzionamento e limita i depositi di grasso.$cz$, who_does_it=$cz$Tu pulisci solo i filtri accessibili secondo il manuale. Per i condotti interni chiama una ditta specializzata.$cz$, what_to_keep=$cz$Ricevuta o rapporto di pulizia dei condotti; annotazione della pulizia dei filtri.$cz$, how_to=$cz$["Spegni la cappa e attendi che sia fredda.","Rimuovi e pulisci solo i filtri previsti dal manuale.","Rimontali asciutti; per i condotti chiama un tecnico."]$cz$::jsonb where is_active and id::text like '1059026c%';
update public.maintenance_templates set description=$cz$La ventilazione meccanica rinnova l’aria della casa. I filtri trattengono polvere e particelle.$cz$, why_it_matters=$cz$Filtri puliti aiutano a mantenere il ricambio d’aria e riducono gli sforzi della macchina.$cz$, who_does_it=$cz$Tu puoi sostituire i filtri accessibili se il manuale lo permette. Altrimenti chiama un tecnico della ventilazione.$cz$, what_to_keep=$cz$Annotazione della sostituzione e ricevuta dei filtri.$cz$, how_to=$cz$["Spegni l’unità come indicato nel manuale.","Estrai i filtri e inserisci quelli compatibili.","Richiudi lo sportello e annota la data."]$cz$::jsonb where is_active and id::text like '010214e7%';
update public.maintenance_templates set description=$cz$I condotti della ventilazione distribuiscono l’aria nelle stanze. Possono raccogliere polvere e depositi nel tempo.$cz$, why_it_matters=$cz$La pulizia professionale aiuta a conservare un buon flusso d’aria.$cz$, who_does_it=$cz$La esegue una ditta specializzata in ventilazione. Tu prenota l’intervento e conserva il rapporto: non smontare i condotti.$cz$, what_to_keep=$cz$Rapporto di ispezione e pulizia dei condotti VMC.$cz$, how_to=null where is_active and id::text like '70b3f1dd%';
update public.maintenance_templates set description=$cz$I filtri del climatizzatore trattengono parte della polvere nell’aria. Se si sporcano, l’aria passa con più difficoltà.$cz$, why_it_matters=$cz$Pulirli aiuta il climatizzatore a funzionare bene e a non sprecare energia.$cz$, who_does_it=$cz$Puoi farlo tu seguendo il manuale, oppure chiedere a un tecnico della climatizzazione.$cz$, what_to_keep=$cz$Annotazione facoltativa della pulizia.$cz$, how_to=$cz$["Spegni il climatizzatore.","Estrai e pulisci i filtri come indicato dal manuale.","Rimontali solo quando sono asciutti."]$cz$::jsonb where is_active and id::text like '13a27be8%';
update public.maintenance_templates set description=$cz$Il differenziale è una protezione del quadro elettrico. Il tasto T serve a controllare che il meccanismo scatti.$cz$, why_it_matters=$cz$La prova può far emergere un guasto della protezione. Non sostituisce una verifica completa dell’impianto.$cz$, who_does_it=$cz$Puoi premere il tasto di prova seguendo il manuale. Se non scatta o non si riarma, chiama un elettricista.$cz$, what_to_keep=$cz$Annotazione facoltativa del test; rapporto dell’elettricista se interviene.$cz$, how_to=$cz$["Avvisa chi è in casa: la corrente potrebbe interrompersi.","Premi solo il tasto T, senza aprire il quadro.","Se scatta, riarmalo; se non scatta, chiama un elettricista."]$cz$::jsonb where is_active and id::text like 'd6e71a15%';
update public.maintenance_templates set description=$cz$La messa a terra aiuta a proteggere dalle dispersioni elettriche. Una verifica strumentale controlla l’impianto.$cz$, why_it_matters=$cz$Il DPR 462/2001, art. 4, vale nei casi soggetti alla disciplina dei luoghi di lavoro. La frequenza dipende dall’impianto: te la conferma il responsabile.$cz$, who_does_it=$cz$Organismo abilitato o ente competente nei casi previsti. Tu non devi fare nulla: se applicabile, organizza l’amministratore.$cz$, what_to_keep=$cz$Verbale di verifica periodica dell’impianto di terra.$cz$, how_to=null where is_active and id::text like '4a74e428%';
update public.maintenance_templates set description=$cz$Imbiancare significa rinnovare la pittura delle pareti. Puoi scegliere un prodotto adatto al tipo di superficie.$cz$, why_it_matters=$cz$Mantiene gli ambienti curati e protegge le finiture dal normale deterioramento.$cz$, who_does_it=$cz$Puoi farlo tu se lavori in sicurezza, oppure rivolgerti a un imbianchino.$cz$, what_to_keep=$cz$Codice della pittura e ricevuta dei materiali, facoltativi.$cz$, how_to=$cz$["Proteggi mobili e pavimenti e pulisci il muro.","Ripara i piccoli segni e applica la pittura indicata.","Rispetta i tempi di asciugatura e arieggia."]$cz$::jsonb where is_active and id::text like '26be7f69%';
update public.maintenance_templates set description=$cz$È la rimozione dello sporco dalla facciata. Il metodo cambia a seconda di intonaco, pittura e rivestimento.$cz$, why_it_matters=$cz$Una pulizia compatibile con i materiali conserva l’aspetto dell’edificio e limita i depositi.$cz$, who_does_it=$cz$Per le facciate chiama un’impresa specializzata tramite l’amministratore. Non usare scale o getti in pressione da solo.$cz$, what_to_keep=$cz$Rapporto di pulizia e fotografie, se disponibili.$cz$, how_to=null where is_active and id::text like 'b91b78f3%';
update public.maintenance_templates set description=$cz$È un prodotto applicato su alcune superfici esterne per ridurre l’assorbimento della pioggia. Non ripara infiltrazioni o crepe.$cz$, why_it_matters=$cz$Può limitare il degrado delle superfici compatibili, se scelto e applicato correttamente.$cz$, who_does_it=$cz$Interviene un’impresa specializzata incaricata dall’amministratore. Tu segnala le zone umide, senza applicare prodotti da solo.$cz$, what_to_keep=$cz$Scheda tecnica del prodotto e rapporto di applicazione.$cz$, how_to=null where is_active and id::text like '04768c36%';
update public.maintenance_templates set description=$cz$Finestre e porte hanno cerniere, guarnizioni e meccanismi di chiusura. Il controllo individua attriti e usura.$cz$, why_it_matters=$cz$Aiuta a evitare blocchi, spifferi e deterioramento dei meccanismi.$cz$, who_does_it=$cz$Tu puoi pulire le parti accessibili e lubrificare solo dove lo indica il manuale. Per le regolazioni chiama un serramentista.$cz$, what_to_keep=$cz$Annotazione dell’intervento; rapporto del serramentista se necessario.$cz$, how_to=$cz$["Pulisci cerniere e guide accessibili.","Usa solo il lubrificante indicato dal produttore.","Apri e chiudi il serramento per verificarne il movimento."]$cz$::jsonb where is_active and id::text like '132b0e68%';
update public.maintenance_templates set description=$cz$Le linee vita sono sistemi di ancoraggio usati dai tecnici che lavorano sul tetto. Devono essere in condizioni adatte prima dell’uso.$cz$, why_it_matters=$cz$In Veneto la LR 61/1985, art. 79-bis, disciplina le misure di sicurezza sulle coperture in determinati interventi edilizi. La frequenza di verifica dipende dal sistema e va confermata dal tecnico.$cz$, who_does_it=$cz$Tecnico competente nei sistemi anticaduta incaricato dall’amministratore. Tu non accedere al tetto e segnala eventuali danni visibili.$cz$, what_to_keep=$cz$Rapporto di ispezione dei dispositivi anticaduta e manuale del sistema.$cz$, how_to=null where is_active and id::text like '1fd67a1e%';
update public.maintenance_templates set description=$cz$Le fosse raccolgono e trattano parte degli scarichi. I degrassatori trattengono i grassi prima che passino nelle tubazioni.$cz$, why_it_matters=$cz$La pulizia riduce cattivi odori, intasamenti e fuoriuscite.$cz$, who_does_it=$cz$Ditta di spurghi autorizzata, incaricata dall’amministratore. Tu segnala odori persistenti e scarichi lenti.$cz$, what_to_keep=$cz$Rapporto di spurgo e formulario rifiuti, quando previsto.$cz$, how_to=null where is_active and id::text like '1e40bc1e%';
update public.maintenance_templates set description=$cz$I pozzetti permettono di controllare le tubazioni di scarico. Fanghi e detriti possono ostacolare il deflusso.$cz$, why_it_matters=$cz$Una pulizia periodica riduce il rischio di intasamenti e allagamenti.$cz$, who_does_it=$cz$Ditta di spurghi incaricata dall’amministratore. Tu segnala rigurgiti, odori e ristagni.$cz$, what_to_keep=$cz$Rapporto di pulizia dei pozzetti e delle condotte.$cz$, how_to=null where is_active and id::text like '225cc536%';
update public.maintenance_templates set description=$cz$Il climatizzatore o la pompa di calore riscalda e, in molti casi, raffresca la casa. Il tecnico controlla il funzionamento dell’impianto.$cz$, why_it_matters=$cz$Aiuta a limitare guasti e consumi. Se l’apparecchio è un impianto termico soggetto al DPR 74/2013, art. 7, la frequenza dipende dalle istruzioni tecniche.$cz$, who_does_it=$cz$Tecnico abilitato per la climatizzazione; certificazione F-gas se necessaria. Tu prenota il controllo e conserva il rapporto.$cz$, what_to_keep=$cz$Rapporto di manutenzione e libretto di impianto aggiornato, se previsto.$cz$, how_to=null where is_active and id::text like 'fc529672%';
update public.maintenance_templates set description=$cz$I pannelli fotovoltaici producono energia dalla luce. Il tecnico controlla inverter, cavi e rendimento dell’impianto.$cz$, why_it_matters=$cz$Permette di individuare guasti e cali di produzione e di mantenere condizioni di sicurezza.$cz$, who_does_it=$cz$Elettricista abilitato per impianti elettrici e personale formato per lavori sul tetto. Tu segnala anomalie all’amministratore.$cz$, what_to_keep=$cz$Rapporto di manutenzione dell’impianto fotovoltaico.$cz$, how_to=null where is_active and id::text like '7296f859%';
update public.maintenance_templates set description=$cz$La manutenzione comprende interventi e controlli sui componenti dell’ascensore. I dispositivi di sicurezza richiedono verifiche specifiche.$cz$, why_it_matters=$cz$Il DPR 162/1999, art. 15, richiede controlli almeno semestrali su alcuni dispositivi di sicurezza. Il manutentore segnala i pericoli e, quando necessario, ferma l’impianto.$cz$, who_does_it=$cz$Manutentore ascensorista abilitato, incaricato dall’amministratore. Tu non intervenire sui meccanismi e segnala rumori o blocchi.$cz$, what_to_keep=$cz$Annotazioni nel libretto dell’ascensore e rapporto di manutenzione.$cz$, how_to=null where is_active and id::text like 'a47686ee%';
update public.maintenance_templates set description=$cz$È un controllo indipendente dalla manutenzione ordinaria. Verifica le condizioni di sicurezza dell’ascensore.$cz$, why_it_matters=$cz$Il DPR 162/1999, art. 13, prevede una verifica ogni due anni. Un esito negativo è comunicato all’autorità competente per i provvedimenti previsti.$cz$, who_does_it=$cz$Organismo di ispezione abilitato o ente competente, incaricato dall’amministratore. Tu non devi fare nulla.$cz$, what_to_keep=$cz$Verbale di verifica periodica biennale dell’ascensore.$cz$, how_to=null where is_active and id::text like 'd582bfad%';
update public.maintenance_templates set description=$cz$Il controllo riguarda caldaia e componenti dell’impianto di riscaldamento. Il tecnico verifica le condizioni di funzionamento.$cz$, why_it_matters=$cz$Il DPR 74/2013, art. 7, richiede controlli secondo le istruzioni tecniche applicabili. La frequenza dipende dal tuo impianto: te la conferma il manutentore.$cz$, who_does_it=$cz$Impresa abilitata per impianti termici, incaricata dall’amministratore. Tu segnala guasti o mancanza di riscaldamento.$cz$, what_to_keep=$cz$Rapporto di manutenzione e libretto di impianto aggiornato.$cz$, how_to=null where is_active and id::text like '08d73253%';
update public.maintenance_templates set description=$cz$È una verifica delle prestazioni energetiche della caldaia. Il tecnico misura i parametri e redige un rapporto.$cz$, why_it_matters=$cz$Il DPR 74/2013, art. 8, disciplina il controllo nei casi previsti. La frequenza dipende dal tuo impianto e dalla Regione: te la conferma il manutentore.$cz$, who_does_it=$cz$Impresa abilitata per impianti termici, incaricata dall’amministratore. Tu non devi fare nulla.$cz$, what_to_keep=$cz$Rapporto di controllo di efficienza energetica (RCEE) e libretto aggiornato.$cz$, how_to=null where is_active and id::text like '55ed1153%';
update public.maintenance_templates set description=$cz$Gli estintori servono a intervenire su piccoli principi d’incendio, solo se puoi farlo in sicurezza. Il controllo verifica presenza ed efficienza.$cz$, why_it_matters=$cz$Per le attività soggette, il DPR 151/2011, art. 6, prevede il mantenimento dei presidi antincendio. La frequenza dipende dai dispositivi e dalle norme tecniche applicabili.$cz$, who_does_it=$cz$Tecnico manutentore antincendio qualificato, incaricato dall’amministratore. Tu segnala estintori mancanti o danneggiati.$cz$, what_to_keep=$cz$Rapporto di controllo, cartellino degli estintori e registro antincendio, se previsto.$cz$, how_to=null where is_active and id::text like 'fc20e159%';
update public.maintenance_templates set description=$cz$Idranti e naspi permettono di usare acqua contro un incendio. Il controllo verifica tubi, valvole e funzionamento.$cz$, why_it_matters=$cz$Per le attività soggette, il DPR 151/2011, art. 6, richiede sistemi antincendio efficienti. La frequenza dipende dall’impianto e dalle norme tecniche applicabili.$cz$, who_does_it=$cz$Tecnico antincendio qualificato, incaricato dall’amministratore. Tu segnala perdite, danni o accessi ostruiti.$cz$, what_to_keep=$cz$Rapporto di controllo della rete idranti e naspi e registro antincendio, se previsto.$cz$, how_to=null where is_active and id::text like 'b25e9c86%';
update public.maintenance_templates set description=$cz$Le porte tagliafuoco rallentano il passaggio di fumo e fiamme. I maniglioni facilitano l’uscita sulle vie di fuga.$cz$, why_it_matters=$cz$Per le attività soggette, il DPR 151/2011, art. 6, richiede la cura delle misure antincendio. La frequenza dipende dai dispositivi e dalle norme tecniche applicabili.$cz$, who_does_it=$cz$Tecnico specializzato nelle chiusure antincendio, incaricato dall’amministratore. Tu non bloccare le porte e segnala difetti.$cz$, what_to_keep=$cz$Rapporto di manutenzione porte tagliafuoco e dispositivi di uscita; registro antincendio, se previsto.$cz$, how_to=null where is_active and id::text like '18452296%';
update public.maintenance_templates set description=$cz$Le lampade di emergenza si accendono quando manca la corrente. Aiutano a individuare le vie di uscita.$cz$, why_it_matters=$cz$Per le attività soggette, il DPR 151/2011, art. 6, richiede di mantenere efficienti i sistemi antincendio. La frequenza delle prove dipende dall’impianto e dalle norme tecniche applicabili.$cz$, who_does_it=$cz$Tecnico specializzato in illuminazione di sicurezza, incaricato dall’amministratore. Tu segnala lampade guaste.$cz$, what_to_keep=$cz$Rapporto delle prove di funzionamento e autonomia; registro antincendio, se previsto.$cz$, how_to=null where is_active and id::text like '4390667e%';
update public.maintenance_templates set description=$cz$Sensori e centralina riconoscono segnali di un possibile incendio. Il sistema può attivare un allarme.$cz$, why_it_matters=$cz$Per le attività soggette, il DPR 151/2011, art. 6, richiede sistemi di sicurezza efficienti. La frequenza dipende dal progetto e dalle norme tecniche applicabili.$cz$, who_does_it=$cz$Tecnico qualificato per impianti di rivelazione, incaricato dall’amministratore. Tu segnala guasti o allarmi anomali.$cz$, what_to_keep=$cz$Rapporto di manutenzione del sistema di rivelazione incendi e registro antincendio, se previsto.$cz$, how_to=null where is_active and id::text like 'dbe47b50%';
update public.maintenance_templates set description=$cz$Sono dispositivi che aiutano a far uscire fumo e calore durante un incendio. Possono essere aperture o sistemi azionati automaticamente.$cz$, why_it_matters=$cz$Per le attività soggette, il DPR 151/2011, art. 6, richiede misure antincendio efficienti. La frequenza dipende dal sistema e dalle norme tecniche applicabili.$cz$, who_does_it=$cz$Tecnico qualificato per sistemi di evacuazione fumo, incaricato dall’amministratore. Tu non azionare i dispositivi per prova.$cz$, what_to_keep=$cz$Rapporto di manutenzione degli evacuatori di fumo e registro antincendio, se previsto.$cz$, how_to=null where is_active and id::text like '8b0ca75c%';
update public.maintenance_templates set description=$cz$I serbatoi accumulano acqua e l’autoclave aiuta a distribuirla. Pulizia e sanificazione eliminano depositi e riducono le contaminazioni.$cz$, why_it_matters=$cz$Aiuta a mantenere condizioni igieniche adeguate nell’impianto idrico.$cz$, who_does_it=$cz$Impresa specializzata incaricata dall’amministratore. Tu segnala acqua con odore o aspetto insolito.$cz$, what_to_keep=$cz$Rapporto di pulizia e sanificazione; eventuali analisi dell’acqua.$cz$, how_to=null where is_active and id::text like 'ad4d4154%';
update public.maintenance_templates set description=$cz$L’autoclave aiuta a mantenere una pressione regolare dell’acqua. Il tecnico controlla pompe, comandi e perdite.$cz$, why_it_matters=$cz$Può prevenire guasti e cali di pressione nei rubinetti.$cz$, who_does_it=$cz$Idraulico o tecnico di pompe incaricato dall’amministratore. Tu segnala cali di pressione o rumori insoliti.$cz$, what_to_keep=$cz$Rapporto di verifica funzionale del gruppo autoclave.$cz$, how_to=null where is_active and id::text like 'b6525a25%';
update public.maintenance_templates set description=$cz$La Legionella è un batterio che può svilupparsi in alcuni impianti idrici. La valutazione cerca situazioni a rischio e stabilisce eventuali controlli dell’acqua.$cz$, why_it_matters=$cz$Aiuta a ridurre il rischio sanitario. La necessità dei campionamenti dipende dall’edificio e dall’impianto: te la conferma il tecnico.$cz$, who_does_it=$cz$Tecnico esperto di rischio legionella e laboratorio competente, incaricati dall’amministratore. Tu segnala anomalie dell’acqua.$cz$, what_to_keep=$cz$Valutazione del rischio legionella e rapporti di campionamento e analisi, se eseguiti.$cz$, how_to=null where is_active and id::text like 'c65893f9%';
update public.maintenance_templates set description=$cz$Il motore apre e chiude cancelli o portoni. Il tecnico controlla movimento, fotocellule e dispositivi di sicurezza.$cz$, why_it_matters=$cz$Riduce blocchi e rischi durante l’apertura e la chiusura.$cz$, who_does_it=$cz$Tecnico di automazioni incaricato dall’amministratore. Tu segnala ostacoli, urti o aperture anomale.$cz$, what_to_keep=$cz$Rapporto di manutenzione del cancello o portone automatico.$cz$, how_to=null where is_active and id::text like '7ed48ab6%';
update public.maintenance_templates set description=$cz$Le pompe sollevano le acque di scarico quando non possono scorrere da sole. Il controllo riguarda pompe, galleggianti e allarmi.$cz$, why_it_matters=$cz$Riduce il rischio di blocchi, cattivi odori e allagamenti.$cz$, who_does_it=$cz$Tecnico di elettropompe o impresa idraulica incaricata dall’amministratore. Tu segnala odori, allarmi o scarichi lenti.$cz$, what_to_keep=$cz$Rapporto di manutenzione dell’impianto di sollevamento reflui.$cz$, how_to=null where is_active and id::text like 'b5a0b565%';
update public.maintenance_templates set description=$cz$Le canne fumarie portano fuori i prodotti della combustione. Depositi e ostruzioni possono ostacolare il passaggio dei fumi.$cz$, why_it_matters=$cz$Aiuta a evitare ostruzioni e problemi di tiraggio, proteggendo il funzionamento degli apparecchi collegati.$cz$, who_does_it=$cz$Tecnico specializzato in sistemi fumari incaricato dall’amministratore. Tu segnala odori di fumo o anomalie e non intervenire.$cz$, what_to_keep=$cz$Rapporto di pulizia e controllo della canna fumaria collettiva.$cz$, how_to=null where is_active and id::text like '9d6ed668%';
